callGraph.callee:
lists::EBOOK
        .entries(&config)
        .iter()
        .map(|name| {
            let page = matches!(name.trim_start_matches('.'), "pdf" | "pdfa" | "epdf");
            (name.clone(), if page { Page::Pdf } else { Page::Comic })
        }).collect

unsafe {
        GetProcessTimes(
            GetCurrentProcess(),
            &mut created,
            &mut exited,
            &mut kernel,
            &mut user,
        )
    }.ok

CONFIG
        .lock()
        .map(|c| {
            let snapshot = (
                c.preview_enabled,
                c.hover_delay_ms,
                c.trigger_key_mode,
                c.same_file_rehover_delay_ms,
                c.settling_delay_ms,
                c.prioritize_keyboard,
                c.trigger_key_enabled,
                c.trigger_key_affect_pin_mode,
                c.tick_ms,
            );
            // Resolved once per config change instead of once per tick: what the tick
            // compares is the spelling, and a spelling that has not changed is a key that
            // has not changed (see the snapshot below).
            let vk = crate::shell::key_input::key_to_vk(&c.trigger_key);
            (snapshot, vk, c.trigger_key.clone())
        }).unwrap_or

registrar
            .RegisterProperty(&UIAutomationPropertyInfo {
                guid: ItemIndex_Property_GUID,
                pProgrammaticName: w!("ItemIndex"),
                r#type: UIAutomationType_Int,
            }).ok
